#### Example 4: React Onboarding Portal Component

```typescript
// portal/src/components/OnboardingWizard.tsx
import React, { useState, useEffect } from 'react';
import { useOktaAuth } from '@okta/okta-react';
import { CheckCircleIcon, ClockIcon, XCircleIcon } from '@heroicons/react/24/solid';

interface OnboardingPhase {
  name: string;
  status: 'pending' | 'in_progress' | 'completed' | 'failed';
  startTime?: string;
  endTime?: string;
  error?: string;
}

interface OnboardingStatus {
  customerId: string;
  customerName: string;
  currentPhase: string;
  phases: OnboardingPhase[];
  estimatedCompletion: string;
}

export const OnboardingWizard: React.FC = () => {
  const { authState, oktaAuth } = useOktaAuth();
  const [onboardingStatus, setOnboardingStatus] = useState<OnboardingStatus | null>(null);
  const [ws, setWs] = useState<WebSocket | null>(null);
  const [formData, setFormData] = useState({
    customerName: '',
    contractId: '',
    dataSovereigntyRegion: 'us-east-1',
    serviceTier: 'basic',
    services: [] as string[],
  });

  // WebSocket connection for real-time updates
  useEffect(() => {
    if (!authState?.isAuthenticated) return;

    const accessToken = authState.accessToken?.accessToken;
    const websocket = new WebSocket(
      `wss://api.gainwell.com/onboarding?token=${accessToken}`
    );

    websocket.onopen = () => {
      console.log('WebSocket connected');
    };

    websocket.onmessage = (event) => {
      const update = JSON.parse(event.data);
      setOnboardingStatus(update);
    };

    websocket.onerror = (error) => {
      console.error('WebSocket error:', error);
    };

    setWs(websocket);

    return () => {
      websocket.close();
    };
  }, [authState]);

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();

    if (!authState?.accessToken) {
      alert('Not authenticated');
      return;
    }

    try {
      const response = await fetch('https://api.gainwell.com/onboardings', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          'Authorization': `Bearer ${authState.accessToken.accessToken}`,
        },
        body: JSON.stringify({
          customer_name: formData.customerName,
          contract_id: formData.contractId,
          data_sovereignty_region: formData.dataSovereigntyRegion,
          service_tier: formData.serviceTier,
          services: formData.services,
        }),
      });

      if (!response.ok) {
        throw new Error('Failed to initiate onboarding');
      }

      const result = await response.json();
      setOnboardingStatus(result);
      alert('Onboarding initiated successfully!');
    } catch (error) {
      console.error('Error initiating onboarding:', error);
      alert('Failed to initiate onboarding. Please try again.');
    }
  };

  const getPhaseIcon = (status: string) => {
    switch (status) {
      case 'completed':
        return <CheckCircleIcon className="w-6 h-6 text-green-500" />;
      case 'in_progress':
        return <ClockIcon className="w-6 h-6 text-blue-500 animate-spin" />;
      case 'failed':
        return <XCircleIcon className="w-6 h-6 text-red-500" />;
      default:
        return <div className="w-6 h-6 rounded-full border-2 border-gray-300" />;
    }
  };

  return (
    <div className="max-w-4xl mx-auto p-6">
      <h1 className="text-3xl font-bold mb-6">Customer Onboarding</h1>

      {!onboardingStatus ? (
        <form onSubmit={handleSubmit} className="space-y-6 bg-white p-6 rounded-lg shadow">
          <div>
            <label className="block text-sm font-medium mb-2">Customer Name</label>
            <input
              type="text"
              value={formData.customerName}
              onChange={(e) => setFormData({ ...formData, customerName: e.target.value })}
              className="w-full px-4 py-2 border rounded-md"
              required
            />
          </div>

          <div>
            <label className="block text-sm font-medium mb-2">Contract ID</label>
            <input
              type="text"
              value={formData.contractId}
              onChange={(e) => setFormData({ ...formData, contractId: e.target.value })}
              placeholder="CNT-123456"
              className="w-full px-4 py-2 border rounded-md"
              required
            />
          </div>

          <div>
            <label className="block text-sm font-medium mb-2">Data Sovereignty Region</label>
            <select
              value={formData.dataSovereigntyRegion}
              onChange={(e) => setFormData({ ...formData, dataSovereigntyRegion: e.target.value })}
              className="w-full px-4 py-2 border rounded-md"
            >
              <option value="us-east-1">Florida (us-east-1)</option>
              <option value="us-west-1">California (us-west-1)</option>
              <option value="us-south-1">Texas (us-south-1)</option>
            </select>
          </div>

          <div>
            <label className="block text-sm font-medium mb-2">Service Tier</label>
            <select
              value={formData.serviceTier}
              onChange={(e) => setFormData({ ...formData, serviceTier: e.target.value })}
              className="w-full px-4 py-2 border rounded-md"
            >
              <option value="basic">Basic</option>
              <option value="premium">Premium</option>
              <option value="enterprise">Enterprise</option>
            </select>
          </div>

          <div>
            <label className="block text-sm font-medium mb-2">Services</label>
            <div className="space-y-2">
              {['rest_api', 'graphql', 's3_exports', 'webhooks'].map((service) => (
                <label key={service} className="flex items-center">
                  <input
                    type="checkbox"
                    checked={formData.services.includes(service)}
                    onChange={(e) => {
                      if (e.target.checked) {
                        setFormData({ ...formData, services: [...formData.services, service] });
                      } else {
                        setFormData({
                          ...formData,
                          services: formData.services.filter((s) => s !== service),
                        });
                      }
                    }}
                    className="mr-2"
                  />
                  <span className="capitalize">{service.replace('_', ' ')}</span>
                </label>
              ))}
            </div>
          </div>

          <button
            type="submit"
            className="w-full bg-blue-600 text-white py-2 rounded-md hover:bg-blue-700 transition"
          >
            Initiate Onboarding
          </button>
        </form>
      ) : (
        <div className="bg-white p-6 rounded-lg shadow">
          <div className="mb-6">
            <h2 className="text-2xl font-semibold">{onboardingStatus.customerName}</h2>
            <p className="text-gray-600">Customer ID: {onboardingStatus.customerId}</p>
            <p className="text-sm text-gray-500">
              Estimated Completion: {onboardingStatus.estimatedCompletion}
            </p>
          </div>

          <div className="space-y-4">
            {onboardingStatus.phases.map((phase, index) => (
              <div key={index} className="flex items-start space-x-4 p-4 border rounded-lg">
                {getPhaseIcon(phase.status)}
                <div className="flex-1">
                  <h3 className="font-medium">{phase.name}</h3>
                  {phase.startTime && (
                    <p className="text-sm text-gray-500">Started: {phase.startTime}</p>
                  )}
                  {phase.endTime && (
                    <p className="text-sm text-gray-500">Completed: {phase.endTime}</p>
                  )}
                  {phase.error && (
                    <p className="text-sm text-red-600 mt-2">Error: {phase.error}</p>
                  )}
                </div>
              </div>
            ))}
          </div>
        </div>
      )}
    </div>
  );
};
